#!/usr/bin/env python3
# V54 steering-wheel fix for ITsMagic. Builds from original V52; no javac needed.
import zipfile,gzip,json,os,sys,copy,uuid,hashlib,base64,zlib
EXPECTED='403044a653ca84e39f301af209cc48c8d33a500566be38836c1bb75de427a103'
OUT='Base agora vai V54 - VOLANTE DINAMICO FISICO CORRIGIDO.itsmbp'
CAR_MOTOR_SOURCE=zlib.decompress(base64.b64decode(''))
CAR_MOTOR_CLASS=zlib.decompress(base64.b64decode(''))
UNO=(-0.3538525,1.4101725,5.9692125)
H113=(-0.8003275,0.9137555,-1.449115)
def sha(path):
 h=hashlib.sha256()
 with open(path,'rb') as f:
  for b in iter(lambda:f.read(1048576),b''):h.update(b)
 return h.hexdigest()
def dyn(t):t['state']='DYNAMIC';t['staticTransform']=False
def pivot(w,p):
 pos=w.get('transform',{}).get('position',{'x':0,'y':0,'z':0});c=copy.deepcopy(w)
 c['transform']['position']={'x':float(pos.get('x',0))-p[0],'y':float(pos.get('y',0))-p[1],'z':float(pos.get('z',0))-p[2]};dyn(c['transform'])
 return {'allowAnimations':True,'clonedByPrefab':False,'dontDestroyOnLoad':False,'enabled':True,'guid':{'DUPLICABLE_GUID':uuid.uuid4().hex,'SINGLE_GUID':uuid.uuid4().hex},'name':'Steering Wheel Pivot','optionsEditor':{'alwaysEnabled':False,'alwaysOpen':False,'depth':0,'open':False,'preventLongClickMenu':False},'selectable':True,'tag':'','transform':{'ignoreParentMatrix':False,'lockScale':True,'position':{'x':p[0],'y':p[1],'z':p[2]},'rotation':{'w':1.0,'x':0.0,'y':0.0,'z':0.0},'scale':{'x':1.0,'y':1.0,'z':1.0},'state':'DYNAMIC','staticTransform':False},'visible':True,'serializedComponents':{'serializedComponentsArray':[]},'serializedChildren':[c]}
def wrap(root,model,p):
 n=0
 def rec(o):
  nonlocal n
  if o.get('name')==model:
   ch=o.get('serializedChildren') or []
   for i,c in enumerate(ch):
    if c.get('name','').lower()=='steeringwheel':ch[i]=pivot(c,p);n+=1
    elif c.get('name')=='Steering Wheel Pivot':
     dyn(c['transform']);
     if c.get('serializedChildren'):dyn(c['serializedChildren'][0]['transform'])
     n+=1
   o['serializedChildren']=ch
  for c in o.get('serializedChildren') or []:rec(c)
 if isinstance(root,list):
  for o in root:rec(o)
 else:rec(root)
 return n
def scene(blob):
 gz=blob[:2]==b'\x1f\x8b';raw=gzip.decompress(blob) if gz else blob;d=json.loads(raw);roots=d.get('serializedObjects',[])
 a=wrap(roots,'uno desmontado',UNO);wrap(roots,'113H',H113)
 if a!=1:raise RuntimeError('steeringwheel do Uno encontrado '+str(a)+' vezes')
 b=json.dumps(d,separators=(',',':'),ensure_ascii=False).encode();return gzip.compress(b) if gz else b
def prefab(blob):
 d=json.loads(blob);wrap(d,'113H',H113);return json.dumps(d,separators=(',',':'),ensure_ascii=False).encode()
def source():
 if len(sys.argv)>1:return os.path.abspath(sys.argv[1])
 hits=[]
 for d in [os.getcwd(),'/sdcard/Download','/storage/emulated/0/Download']:
  if os.path.isdir(d):
   hits += [os.path.join(d,n) for n in os.listdir(d) if n.lower().endswith('.itsmbp') and 'v52' in n.lower()]
 if not hits:raise SystemExit('Uso: python build_v54_volante.py "/sdcard/Download/SEU_V52.itsmbp"')
 return max(hits,key=os.path.getmtime)
def main():
 s=source()
 if not zipfile.is_zipfile(s):raise SystemExit('V52 invalido')
 if sha(s)!=EXPECTED:print('AVISO: este V52 difere da base original; vou tentar mesmo assim.')
 out=os.path.join(os.path.dirname(s),OUT)
 repl={'cave nous car/Files/ACP/Core/Scripts/CarSystem/CarMotor.java':CAR_MOTOR_SOURCE,'cave nous car/Files/ACP/Core/Scripts/CarSystem/CarMotor.meta/jc.javac':CAR_MOTOR_SOURCE,'cave nous car/Files/ACP/Core/Scripts/CarSystem/CarMotor.meta/CarMotor.class':CAR_MOTOR_CLASS,'cave nous car/JAVARuntime/JAVARuntime/CarMotor.class':CAR_MOTOR_CLASS,'cave nous car/_PROJECT/Scripts/_JContainer.meta/CarMotor.class':CAR_MOTOR_CLASS}
 with zipfile.ZipFile(s) as zin:
  for n in ['cave nous car/_EDITOR/currentScene.scn','cave nous car/Files/Worlds/World.world']:repl[n]=scene(zin.read(n))
  n='cave nous car/Files/113h/113H.meta/113H.go';repl[n]=prefab(zin.read(n))
  with zipfile.ZipFile(out,'w') as zout:
   for info in zin.infolist():zout.writestr(copy.copy(info),repl.get(info.filename,zin.read(info.filename)))
 with zipfile.ZipFile(out) as z:
  bad=z.testzip()
  if bad:raise RuntimeError('ZIP invalido: '+bad)
 print('OK:',out);print('SHA-256:',sha(out));print('Tamanho:',os.path.getsize(out),'bytes')
if __name__=='__main__':main()
